class Solution:
    def maxValue(self, n, index, maxSum):
        answer = 1
        value = 1
        while True:
            total = 0
            for i in range(n):
                total += max(1, value - abs(i - index))
                if total > maxSum:
                    break
            if total > maxSum:
                return answer
            answer = value
            value += 1

